          return original.call(this, content, mode)
        }
        proto.prompt.__dshSubagentImageV4 = true
        patched = true
        return true
      } catch (error) {
        return false
      }
    }

    if (tryPatch() === false) {
      const stop = ctx.interval(() => {
        if (tryPatch() === true && typeof stop === 'function') stop()
      }, 1000)
    }
