            React.createElement('span', { className: 'plinst-stars' }, React.createElement(StarIcon, null), String(r.stars))),
          typeof r.description === 'string' && r.description.length > 0 ? React.createElement('div', { className: 'plinst-desc' }, r.description) : null,
          Array.isArray(r.topics) && r.topics.length > 0 ? React.createElement('div', { className: 'plinst-topics' }, r.topics.map((t) => React.createElement('span', { key: t, className: 'plinst-topic' }, String(t)))) : null,
          React.createElement('div', { className: 'plinst-actions' },
            isInstalled === true ? React.createElement('span', { className: 'plinst-topic', style: { color: '#16a34a', background: 'rgba(22,163,74,.1)' } }, '已安装') : null,
            React.createElement('button', {
              type: 'button',
              className: 'plinst-btn plinst-btn-primary',
              disabled: installing !== '',
              onClick: () => install(r.repo),
            }, installing === r.repo ? '安装中…' : (isInstalled === true ? '更新' : '安装'))))
      }).filter((node) => node !== null)

      const installedRows = installed === null || !Array.isArray(installed.registry) || installed.registry.length === 0 ? null : installed.registry.map((r) => {
        if (r === null || typeof r !== 'object') return null
        return React.createElement('div', { key: r.name, className: 'plinst-row' },
          React.createElement('span', { className: 'plinst-row-name', title: r.dir }, String(r.name)),
          React.createElement('span', { style: { fontSize: 11, color: 'var(--dsw-alias-label-tertiary, #9ca3af)' } }, String(r.dir)))
      }).filter((node) => node !== null)

      const overlay = open === false ? null : React.createElement('div', { className: 'plinst-overlay' },
        React.createElement('div', { className: 'plinst-backdrop', onClick: () => setOpen(false) }),
        React.createElement('div', { className: 'plinst-panel', role: 'dialog', 'aria-modal': 'true' },
          React.createElement('div', { className: 'plinst-header' },
            React.createElement('div', {},
              React.createElement('div', { className: 'plinst-title' }, '插件市场'),
              React.createElement('div', { className: 'plinst-subtitle' }, 'GitHub topic dsh-plugin · 安装社区插件到本地 DSH')),
            React.createElement('button', { type: 'button', className: 'plinst-close', onClick: () => setOpen(false), 'aria-label': '关闭' }, React.createElement(CloseIcon, null))),
          error !== null ? React.createElement('div', { className: 'plinst-error' }, error) : null,
          note !== null ? React.createElement('div', { className: 'plinst-note' }, note) : null,
          React.createElement('div', { className: 'plinst-body' },
            React.createElement('div', { className: 'plinst-toolbar' },
              React.createElement('input', {
                className: 'plinst-search',
                type: 'search',
                placeholder: '搜索插件仓库…（默认展示 dsh-plugin 热门）',
                value: query,
                onChange: (e) => setQuery(e.target.value),
                onKeyDown: (e) => { if (e.key === 'Enter') submitSearch() },
              }),
              React.createElement('button', { type: 'button', className: 'plinst-btn', onClick: submitSearch }, '搜索')),
            repos === null ? React.createElement('div', { className: 'plinst-empty' }, '加载中…')
              : (repoRows.length === 0 ? React.createElement('div', { className: 'plinst-empty' }, '没有匹配的仓库。') : cards),
            installedRows !== null ? React.createElement('div', null,
              React.createElement('div', { className: 'plinst-section' }, '已安装'),
              installedRows) : null)))

      return React.createElement('div', { className: 'plinst-root' },
        React.createElement('button', {
          type: 'button',
          className: 'plinst-badge',
          'aria-haspopup': 'dialog',
          'aria-expanded': open === true,
          title: '插件市场（浏览并安装社区插件）',
          onClick: () => { setOpen((wasOpen) => !wasOpen); setError(null); setNote(null) },
        },
          React.createElement(StoreIcon, null),
          wide === true ? React.createElement('span', { style: { textOverflow: 'ellipsis', whiteSpace: 'nowrap', minWidth: 0, overflow: 'hidden' } }, '市场') : null),
        overlay)
    }

    slots.inject('sidebar.footer.action', () => slots.register(
      {
        name: 'sidebar.footer.action',
        id: 'plugin-market',
        order: 2,
        label: () => '市场',
      },
      MarketPanel,
    ))
  },
}

plugins.hostCode:
function errText(error) {
  if (error !== null && typeof error === 'object' && typeof error.message === 'string') return error.message
  return String(error)
}
function jsonText(value) {
  return JSON.stringify(value, null, 2)
}
function textOf(collected) {
  if (collected !== null && typeof collected === 'object' && typeof collected.text === 'string') return collected.text
  return ''
}

// sfind host half: session_find tool — keyword search over session ids and
// titles without dumping the whole session list. Titles come from the
// projection cache; live status from the in-memory session store.
const PROJCACHE = '/home/alex/.dsh/storages/session_projcache.json'

return {
  inject: ['shell'],
  apply(ctx) {
    const shell = ctx.get('shell')
    if (shell === undefined) return
    const sessions = ctx.get('sessions')

    async function sh(command, timeoutMs, maxBytes) {
      const spec = shell.resolve({ command, timeoutMs: timeoutMs ?? 10000, stdoutMaxBytes: maxBytes ?? 524288 })
      const r = await shell.run(spec)
      return { exitCode: r.exitCode, text: textOf(r.stdout), err: textOf(r.stderr) }
    }

    const tool = harness.defineTool({
      name: 'session_find',
      description: 'Find sessions by keyword (session id substring or title substring) and return a compact list of matches with live status. Use instead of session_list when you know a title or id fragment, to save context. Call session_list only when you need the full roster.',
      parameters: {
        query: { type: 'string', required: true, description: 'Keyword matched (case-insensitive) against session ids and titles.' },
        limit: { type: 'number', description: 'Max results (default 20, cap 50).' },
      },
      output: {
        schema: { type: 'string' },
        render(_args, value) { return [{ type: 'text', text: typeof value === 'string' ? value : String(value) }] },
      },
      async execute(args) {
        try {
          const q = String(args !== null && typeof args === 'object' ? args.query ?? '' : '').trim().toLowerCase()
          if (q === '') return jsonText({ ok: false, error: 'query is required' })
          const cap = typeof args.limit === 'number' && args.limit > 0 ? Math.min(Math.floor(args.limit), 50) : 20

          const titles = {}
          const script = "const fs=require('fs');const d=JSON.parse(fs.readFileSync('" + PROJCACHE + "','utf8'));const t=d.tables&&d.tables.sessions?d.tables.sessions:{};const out={};for(const id of Object.keys(t)){const r=t[id];const v=r&&r.rows&&r.rows.title&&r.rows.title.val;if(typeof v==='string'&&v.length>0)out[id]=v}console.log(JSON.stringify(out))"
          const res = await sh('node -e ' + JSON.stringify(script), 8000)
          if (res.exitCode === 0 && res.text.length > 0) {
            try { Object.assign(titles, JSON.parse(res.text)) } catch (error) { /* best-effort titles */ }
          }

          const results = []
          for (const [id, title] of Object.entries(titles)) {
            if (id.toLowerCase().includes(q) || String(title).toLowerCase().includes(q)) {
              results.push({ sessionId: id, title: title, live: sessions !== undefined && typeof sessions.get === 'function' ? sessions.get(id) !== undefined : false })
            }
            if (results.length >= cap) break
          }
          // fall back to live ids (sessions without a cached title)
          if (results.length < cap && sessions !== undefined && typeof sessions.list === 'function') {
            for (const s of sessions.list()) {
              const id = s !== null && typeof s === 'object' && typeof s.id === 'string' ? s.id : ''
              if (id === '' || id.toLowerCase().includes(q) === false) continue
              if (results.some((r) => r.sessionId === id)) continue
              results.push({ sessionId: id, title: null, live: true })
              if (results.length >= cap) break
            }
          }
          return jsonText({ ok: true, query: String(args.query), count: results.length, sessions: results })
        } catch (error) {
          return jsonText({ ok: false, error: errText(error) })
        }
      },
    })
    const dispose = harness.registerTool(ctx, tool)
    ctx.effect(() => () => { try { dispose() } catch (error) { /* best-effort */ } })
  },
}

// subflt host half v2: subagent report/steer channel + same-turn dedupe.
//
// Official dsh-subagent queues relay reports via followup (next turn) while
// the settlement notice steers into the current turn — duplicated content,
// scrambled timeline. This plugin:
//   1. wraps subagents.reportFrom so reports are STEERED into the parent's
//      current turn when it is busy (same policy as settlement), and
//   2. dedupes in pre-step: a subagent-report whose child ALSO delivered a
//      settlement notice in the same turn is dropped (merged); mid-flight
//      progress reports without a settlement survive.
return {
  apply(ctx) {
    const subagents = ctx.get('subagents')
    if (subagents !== undefined && typeof subagents.reportFrom === 'function' && subagents.reportFrom.__rptsteer !== true) {
      const original = subagents.reportFrom.bind(subagents)
      const bridged = async (child, content, options) => {
        const agents = ctx.get('agents')
        const parentId = child !== null && typeof child === 'object' && child.session !== null && typeof child.session === 'object' && child.session.header !== null && typeof child.session.header === 'object' ? child.session.header.parentSession : undefined
        const parent = parentId === undefined || agents === undefined || typeof agents.get !== 'function' ? undefined : agents.get(parentId)
        if (parent === undefined) {
          // Unresolvable parent: keep official semantics (authorization + queued delivery).
          return original(child, content, options)
        }
        const blocks = Array.isArray(content) ? content : []
        const message = {
          id: 'rpt-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8),
          role: 'user',
          content: [{ type: 'text', text: 'Background subagent ' + child.id + ' reported:' }, ...blocks],
          source: { kind: 'subagent-report', form: 'relay', senderSessionId: child.id },
        }
        try {
          if (parent.status === 'idle') parent.followup(message)
          else parent.steer(message)
        } catch (error) {
          // Parent rejected the steer — fall back to the official relay.
          return original(child, content, options)
        }
        return message.id
      }
      bridged.__rptsteer = true
      subagents.reportFrom = bridged
    }

    ctx.on('agent/pre-step', async (payload, next) => {
      const decision = await next()
      if (!Array.isArray(decision.messages)) return decision
      const settledChildren = new Set()
      for (const m of decision.messages) {
        if (m !== null && typeof m === 'object' && m.source !== null && typeof m.source === 'object' && m.source.kind === 'subagent-settled' && typeof m.source.senderSessionId === 'string') {
          settledChildren.add(m.source.senderSessionId)
        }
      }
      const messages = decision.messages.filter((m) => {
        if (m === null || typeof m !== 'object' || m.source === null || typeof m.source !== 'object') return true
        if (m.source.kind !== 'subagent-report') return true
        // Drop only the report that duplicates a same-turn settlement.
        return typeof m.source.senderSessionId === 'string' ? !settledChildren.has(m.source.senderSessionId) : true
      })
      return { ...decision, messages }
    }, { prepend: true })
  },
}
